//! Page preview: sends the generated Typst source to the worker (debounced)
//! and shows the visible pages as SVG images. Never blocks typing: while the
//! worker is busy, the old pages stay and at most one request waits.

use std::cell::RefCell;
use std::rc::Rc;

use absatz_core::protocol::{FromWorker, ToWorker};
use wasm_bindgen::{JsCast, JsValue, closure::Closure};
use web_sys::{
    Blob, BlobPropertyBag, Element, HtmlElement, MessageEvent, Url, Worker, WorkerOptions,
    WorkerType,
};

use crate::storage;

/// Script generated by Trunk for the worker binary (`data-loader-shim`).
pub const WORKER_URL: &str = "./worker_loader.js";
/// Wait this long after the last change before typesetting.
const DEBOUNCE_MS: i32 = 100;
/// Space between pages in CSS px; must match `.preview { gap }`.
const PAGE_GAP: f64 = 12.0;

/// What the preview needs from the document at the moment it typesets.
pub struct Snapshot {
    /// Typst source (`codegen::typst`).
    pub source: String,
    /// Document to autosave, if autosave is on.
    pub save: Option<String>,
}

struct State {
    worker: Worker,
    pane: Element,
    status: Element,
    snapshot: Box<dyn Fn() -> Snapshot>,
    /// The document changed since the last request.
    dirty: bool,
    /// A request is running (or the worker is still starting).
    busy: bool,
    /// Something happened while busy; ask again when the answer arrives.
    again: bool,
    timer: Option<i32>,
}

#[derive(Clone)]
pub struct Preview(Rc<RefCell<State>>);

impl Preview {
    pub fn start(
        pane: Element,
        status: Element,
        snapshot: impl Fn() -> Snapshot + 'static,
    ) -> Option<Preview> {
        let options = WorkerOptions::new();
        options.set_type(WorkerType::Module);
        let worker = Worker::new_with_options(WORKER_URL, &options).ok()?;
        status.set_text_content(Some("Satz wird geladen …"));
        let preview = Preview(Rc::new(RefCell::new(State {
            worker: worker.clone(),
            pane: pane.clone(),
            status,
            snapshot: Box::new(snapshot),
            dirty: true,
            busy: true,
            again: false,
            timer: None,
        })));

        let this = preview.clone();
        let on_message = Closure::<dyn Fn(MessageEvent)>::new(move |ev: MessageEvent| {
            this.on_message(ev.data())
        });
        worker.set_onmessage(Some(on_message.as_ref().unchecked_ref()));
        on_message.forget();

        let this = preview.clone();
        let on_scroll = Closure::<dyn Fn()>::new(move || this.flush());
        let _ = pane.add_event_listener_with_callback("scroll", on_scroll.as_ref().unchecked_ref());
        on_scroll.forget();
        Some(preview)
    }

    /// The document changed: typeset soon. Cheap; safe to call per keystroke.
    pub fn schedule(&self) {
        let Some(window) = web_sys::window() else {
            return;
        };
        let mut st = self.0.borrow_mut();
        st.dirty = true;
        st.status.set_text_content(Some("wird aktualisiert …"));
        if let Some(timer) = st.timer.take() {
            window.clear_timeout_with_handle(timer);
        }
        let this = self.clone();
        let fire = Closure::once_into_js(move || this.flush());
        st.timer = window
            .set_timeout_with_callback_and_timeout_and_arguments_0(
                fire.unchecked_ref(),
                DEBOUNCE_MS,
            )
            .ok();
    }

    /// Download the document as PDF.
    pub fn pdf(&self) {
        let st = self.0.borrow();
        let source = (st.snapshot)().source;
        st.status.set_text_content(Some("PDF wird erzeugt …"));
        post(&st.worker, &ToWorker::Pdf { source });
    }

    /// Send one request for the current state, unless one is running.
    fn flush(&self) {
        let mut st = self.0.borrow_mut();
        if st.busy {
            st.again = true;
            return;
        }
        let source = st.dirty.then(|| {
            let snapshot = (st.snapshot)();
            if let Some(json) = snapshot.save {
                wasm_bindgen_futures::spawn_local(async move {
                    let _ = storage::save(&json).await;
                });
            }
            snapshot.source
        });
        st.dirty = false;
        let (first, last) = visible_pages(&st.pane);
        post(
            &st.worker,
            &ToWorker::Update {
                source,
                first,
                last,
            },
        );
        st.busy = true;
    }

    fn on_message(&self, data: JsValue) {
        let Some(text) = data.as_string() else {
            // The only binary message is the PDF.
            download(
                &js_sys::Uint8Array::new(&data),
                "application/pdf",
                "dokument.pdf",
            );
            self.0.borrow().status.set_text_content(None);
            return;
        };
        let mut st = self.0.borrow_mut();
        st.busy = false;
        let mut again = std::mem::take(&mut st.again);
        match FromWorker::from_json(&text) {
            Ok(FromWorker::Ready) => again = true,
            Ok(FromWorker::Pages {
                count,
                first,
                svgs,
                error,
            }) => {
                show_pages(&st.pane, count, first, &svgs);
                // The page count may have changed what is visible.
                let (a, b) = visible_pages(&st.pane);
                again |= error.is_none()
                    && (a..=b).any(|i| {
                        page_image(&st.pane, i).is_some_and(|img| !img.has_attribute("src"))
                    });
                let status = match &error {
                    Some(e) => format!("Satzfehler – Seiten zeigen den letzten Stand. ({e})"),
                    None if st.dirty => "wird aktualisiert …".into(),
                    None => format!("{count} {}", if count == 1 { "Seite" } else { "Seiten" }),
                };
                st.status.set_text_content(Some(&status));
            }
            Ok(FromWorker::Error { message }) => st
                .status
                .set_text_content(Some(&format!("Fehler: {message}"))),
            Ok(FromWorker::Bench(_)) | Err(_) => {}
        }
        drop(st);
        if again {
            self.flush();
        }
    }
}

fn post(worker: &Worker, message: &ToWorker) {
    let _ = worker.post_message(&JsValue::from_str(&message.to_json()));
}

/// Indices of the first and last page in view (pages all have the same height).
fn visible_pages(pane: &Element) -> (usize, usize) {
    let Some(page) = pane.first_element_child() else {
        return (0, 1);
    };
    let height = page.get_bounding_client_rect().height() + PAGE_GAP;
    let top = f64::from(pane.scroll_top());
    let bottom = top + f64::from(pane.client_height());
    ((top / height) as usize, (bottom / height) as usize)
}

fn page_image(pane: &Element, index: usize) -> Option<Element> {
    pane.children().item(index as u32)?.first_element_child()
}

/// Make the pane hold `count` page frames and fill in the rendered ones.
fn show_pages(pane: &Element, count: usize, first: usize, svgs: &[String]) {
    let Some(dom) = pane.owner_document() else {
        return;
    };
    while (pane.child_element_count() as usize) > count {
        if let Some(last) = pane.last_element_child() {
            release(last.first_element_child());
            last.remove();
        }
    }
    while (pane.child_element_count() as usize) < count {
        let (Ok(frame), Ok(img)) = (dom.create_element("div"), dom.create_element("img")) else {
            return;
        };
        frame.set_class_name("page");
        let _ = img.set_attribute("alt", &format!("Seite {}", pane.child_element_count() + 1));
        let _ = frame.append_child(&img);
        let _ = pane.append_child(&frame);
    }
    for (i, svg) in svgs.iter().enumerate() {
        let Some(img) = page_image(pane, first + i) else {
            continue;
        };
        release(Some(img.clone()));
        if let Some(url) = blob_url(&JsValue::from_str(svg), "image/svg+xml") {
            let _ = img.set_attribute("src", &url);
        }
    }
}

/// Free the image data an `<img>` pointed to.
fn release(img: Option<Element>) {
    if let Some(url) = img.and_then(|i| i.get_attribute("src")) {
        let _ = Url::revoke_object_url(&url);
    }
}

fn blob_url(data: &JsValue, mime: &str) -> Option<String> {
    let options = BlobPropertyBag::new();
    options.set_type(mime);
    let blob =
        Blob::new_with_blob_sequence_and_options(&js_sys::Array::of1(data), &options).ok()?;
    Url::create_object_url_with_blob(&blob).ok()
}

fn download(data: &JsValue, mime: &str, name: &str) {
    let Some(dom) = web_sys::window().and_then(|w| w.document()) else {
        return;
    };
    let (Some(url), Ok(link)) = (blob_url(data, mime), dom.create_element("a")) else {
        return;
    };
    let _ = link.set_attribute("href", &url);
    let _ = link.set_attribute("download", name);
    link.unchecked_ref::<HtmlElement>().click();
    let _ = Url::revoke_object_url(&url);
}
